package onboarding

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"hlcp/internal/localapi"
	"hlcp/internal/setup"
	"hlcp/internal/transport"
	"net"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

var ErrControllerOptions = errors.New("onboarding: controller setup options or credentials are invalid")

type ControllerOptions struct {
	ListenAddress, ServerName string
	AdmittedNodes             []string
}

// Tokens are imported snapshots, never generated by planning or reported.
type ControllerCredentials struct{ operator, observer []byte }

func NewControllerCredentials(operator, observer []byte) (ControllerCredentials, error) {
	a, e1 := localapi.ParseToken(operator)
	b, e2 := localapi.ParseToken(observer)
	if e1 != nil || e2 != nil || a == b {
		return ControllerCredentials{}, ErrControllerOptions
	}
	return ControllerCredentials{[]byte(a + "\n"), []byte(b + "\n")}, nil
}
func (ControllerCredentials) MarshalJSON() ([]byte, error) {
	return []byte(`{"controller_credentials":"redacted"}`), nil
}
func (c ControllerCredentials) String() string   { data, _ := c.MarshalJSON(); return string(data) }
func (c ControllerCredentials) GoString() string { return c.String() }

type ControllerSetup struct{ plan *AgentSetup }

func (s *ControllerSetup) Preview() setup.Preview {
	if s == nil || s.plan == nil {
		return setup.Preview{ReadOnly: true}
	}
	return s.plan.Preview()
}
func (s ControllerSetup) MarshalJSON() ([]byte, error) { return json.Marshal(s.Preview()) }
func (s ControllerSetup) String() string               { data, _ := s.MarshalJSON(); return string(data) }
func (s ControllerSetup) GoString() string             { return s.String() }
func (s *ControllerSetup) Close() error {
	if s == nil || s.plan == nil {
		return nil
	}
	return s.plan.Close()
}
func (s *ControllerSetup) Apply(ctx context.Context, confirmed bool) (setup.ApplyResult, error) {
	if s == nil || s.plan == nil {
		return setup.ApplyResult{}, ErrControllerOptions
	}
	return s.plan.Apply(ctx, confirmed)
}

const controllerPolicy = `{"version":1,"principals":[{"id":"operator","role":"operator","token_file":"api.token","scope":{"all_nodes":true}},{"id":"observer","role":"observer","token_file":"observer.token","scope":{"all_nodes":true}}]}
`

func PlanController(ctx context.Context, directory string, owner setup.Owner, options ControllerOptions, material ImportedTLS, credentials ControllerCredentials, now time.Time) (*ControllerSetup, error) {
	if !filepath.IsAbs(directory) || filepath.Clean(directory) != directory || directory == "/" || len(directory) > 4096 ||
		strings.ContainsRune(directory, 0) || !validControllerListen(options.ListenAddress) {
		return nil, ErrControllerOptions
	}
	if !validHost(options.ServerName) {
		return nil, ErrControllerOptions
	}
	identity := Identity{Role: "controller", ServerName: options.ServerName}
	if _, err := material.Validate(identity, now); err != nil {
		return nil, err
	}
	// Clone/normalize and revalidate even zero-value or same-package credentials.
	tokens, err := NewControllerCredentials(credentials.operator, credentials.observer)
	if err != nil {
		return nil, err
	}
	nodes := append([]string{}, options.AdmittedNodes...)
	sort.Strings(nodes)
	nodeData, err := json.Marshal(nodes)
	if err != nil {
		return nil, ErrControllerOptions
	}
	if _, err := transport.ParseAllowedNodes(nodeData); err != nil {
		return nil, ErrControllerOptions
	}
	validatePolicy := func(data []byte) error {
		_, err := localapi.ParsePolicy(data, func(name string) (string, error) {
			switch name {
			case "api.token":
				return localapi.ParseToken(tokens.operator)
			case "observer.token":
				return localapi.ParseToken(tokens.observer)
			}
			return "", ErrControllerOptions
		})
		return err
	}
	validateCA := func(data []byte) error { _, err := validCA(data, now); return err }
	validateCert := func(data []byte) error {
		certs, err := parseCertificates(data)
		if err != nil {
			return err
		}
		return validateLeaf(certs[0], identity, now)
	}
	validateToken := func(data []byte) error { _, err := localapi.ParseToken(data); return err }
	intents := []setup.Intent{
		{Name: "controller.crt", Data: bytes.Clone(material.certificate), Mode: 0600, Validate: validateCert},
		{Name: "controller.key", Data: bytes.Clone(material.key), Mode: 0600, Validate: validatePrivateKey},
		{Name: "ca.crt", Data: bytes.Clone(material.peerTrust), Mode: 0600, Validate: validateCA},
		{Name: "issuer-ca.crt", Data: bytes.Clone(material.issuerTrust), Mode: 0600, Validate: validateCA},
		{Name: "controller.env", Data: []byte("HLCP_AGENT_LISTEN=" + options.ListenAddress + "\n"), Mode: 0600, Validate: validateControllerEnv},
		{Name: "api-policy.json", Data: []byte(controllerPolicy), Mode: 0600, Validate: validatePolicy},
		{Name: "api.token", Data: tokens.operator, Mode: 0600, Validate: validateToken},
		{Name: "observer.token", Data: tokens.observer, Mode: 0600, Validate: validateToken},
		{Name: "nodes.json", Data: nodeData, Mode: 0600, Validate: func(data []byte) error { _, err := transport.ParseAllowedNodes(data); return err }},
	}
	plan, err := planFiles(ctx, directory, owner, intents)
	if err != nil {
		return nil, err
	}
	return &ControllerSetup{plan}, nil
}

func validControllerListen(value string) bool {
	host, port, err := net.SplitHostPort(value)
	ip := net.ParseIP(host)
	number, numberErr := strconv.Atoi(port)
	return err == nil && ip != nil && !ip.IsUnspecified() && numberErr == nil && number >= 1024 && number <= 65535 && port == strconv.Itoa(number)
}
func validateControllerEnv(data []byte) error {
	if len(data) > 4096 {
		return ErrControllerOptions
	}
	found := false
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		name, value, ok := strings.Cut(line, "=")
		if !ok || name != "HLCP_AGENT_LISTEN" || found || !validControllerListen(value) {
			return ErrControllerOptions
		}
		found = true
	}
	if !found {
		return ErrControllerOptions
	}
	return nil
}
